"""Rebind unchanged component/datasheet arithmetic to the current copper revision."""
import json,pathlib,subprocess,hashlib
root=pathlib.Path(__file__).resolve().parents[1];source=root/'artifacts/board.circuit.json';j=json.loads(source.read_text());base=subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip();old=json.loads(subprocess.check_output(['git','show',base+':artifacts/board.circuit.json'],cwd=root));keys=['manufacturer_part_number','resistance','capacitance','inductance','supplier_part_numbers']
def component_data(records):return {e['name']:{k:e.get(k)for k in keys}for e in records if e['type']=='source_component'}
a,b=component_data(old),component_data(j);assert a==b,'Component values/identities changed: repeat primary power review'
p=root/'artifacts/engineering/service-power-review.json';review=json.loads(p.read_text());review['current_routing_revision_binding']={'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'unchanged_component_data_from_commit':base,'component_data_sha256':hashlib.sha256(json.dumps(b,sort_keys=True,separators=(',',':')).encode()).hexdigest(),'scope':'Existing primary datasheet/component arithmetic remains applicable because all component identities/values are unchanged. Current trace/via resistance and outer-layer checks are separately recorded in trace-width-review.json and outer-power-routing.md. No hardware test or regulator/transient qualification is claimed.'};p.write_text(json.dumps(review,indent=2)+'\n');print('Bound unchanged primary component/power evidence')
